 string SelectedSource(){return files.SelectedItem as string??(files.Items.Count>0?files.Items[0].ToString():null);}
 async Task UpdateSelection(){if(buildingUI)return;summaryTitle.Text=files.Items.Count>0?Path.GetFileName(SelectedSource()):"Файлы не выбраны";if(layoutMode==2)await mediaPreview.LoadSource(SelectedSource());}
 void RemoveSelectedFile(){if(appBusy)return;if(files.SelectedIndex>=0)files.Items.RemoveAt(files.SelectedIndex);if(refreshFiles!=null)refreshFiles();}
 void DrawWorkspaceFile(object sender,DrawItemEventArgs e){if(e.Index<0)return;var g=e.Graphics;bool selected=(e.State&DrawItemState.Selected)!=0;using(var b=new SolidBrush(selected?Color.FromArgb(56,49,73):Skin.Card))g.FillRectangle(b,e.Bounds);string file=files.Items[e.Index].ToString(),ext=Path.GetExtension(file).TrimStart('.').ToUpperInvariant();int row=e.Bounds.Y,x=e.Bounds.X;Glyph.File(g,new Rectangle(x+8,row+12,46,46),ext,Color.FromArgb(196,177,238));int available=Math.Max(30,e.Bounds.Width-116);TextRenderer.DrawText(g,Path.GetFileName(file),Font,new Rectangle(x+70,row+10,available,25),Skin.Text,TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter);string detail=ext;try{detail+=" · "+(new FileInfo(file).Length/1048576d).ToString("0.00")+" МБ";}catch{}using(var small=new Font("Segoe UI",9))TextRenderer.DrawText(g,detail,small,new Rectangle(x+70,row+39,available,22),Skin.Muted,TextFormatFlags.EndEllipsis);TextRenderer.DrawText(g,"×",Font,new Rectangle(e.Bounds.Right-35,row+18,28,30),Skin.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);using(var pen=new Pen(Skin.Line))g.DrawLine(pen,x+8,row+75,e.Bounds.Right-8,row+75);}
 int GetMp3Bitrate(){return new[]{96,128,192,256,320}[Math.Max(0,Math.Min(4,qualityChoice.SelectedIndex))];}
 void UpdateCategory(){if(formatTitle==null||buildingUI)return;for(int i=0;i<5;i++){categoryButtons[i].Primary=i==type.SelectedIndex;categoryButtons[i].Invalidate();}screenTitle.Text=type.SelectedIndex==4?format.Text:type.SelectedIndex==3?"Текст из документов":"Конвертер файлов";noteLabel.Text=type.SelectedIndex==3?"PDF и фото: OCR на русском и английском. Оформление не переносится.":"Исходники сохраняются. Файлы обрабатываются на компьютере.";LayoutWorkspace();}
 void OpenWorkspaceGifEditor(){if(appBusy)return;try{CommitInlineGif();using(var editor=new GifEditor(SelectedSource(),root,toolPanel.Snapshot(0).Gif)){if(editor.ShowDialog(this)==DialogResult.OK){toolPanel.Gif=editor.Result;toolPanel.Configure(0);gifInspector.LoadOptions(editor.Result);if(editor.Result.MaxBytes>0){activePreset=0;presetChoice.Text="GIF до 10 МБ";}else if(activePreset==0)ClearPreset();LayoutWorkspace();}}}catch(Exception ex){ShowNotice(ex.Message);}}
 async Task HandleWorkspaceRun(){if(appBusy)return;if(layoutMode==1&&wizardStep==0){if(files.Items.Count==0){ShowNotice("Добавьте хотя бы один файл.");return;}wizardStep=1;body.MoveTo(0);LayoutWorkspace();return;}if(layoutMode==1&&wizardStep==2){wizardStep=0;body.MoveTo(0);LayoutWorkspace();return;}try{CommitInlineGif();}catch(Exception ex){ShowNotice(ex.Message);return;}await ConvertFiles();}
 void PrepareWorkspaceBatch(){lastOutputs.Clear();steps.HasResults=false;SetWorkspaceBusy(true);}
 void RecordWorkspaceOutput(string path){lastOutputs.Add(path);}
 void CompleteWorkspaceBatch(){SetWorkspaceBusy(false);if(lastOutputs.Count>0){outputFiles.Items.Clear();foreach(string path in lastOutputs)outputFiles.Items.Add(Path.GetFileName(path));resultTitle.Text="Готово · "+lastOutputs.Count+" файлов";steps.HasResults=true;if(layoutMode==1){wizardStep=2;body.MoveTo(0);}}LayoutWorkspace();}
 void SetWorkspaceBusy(bool busy){appBusy=busy;gifInspector.Enabled=!busy;foreach(var button in operationButtons)button.Enabled=!busy;layoutSwitcher.Enabled=!busy;wizardBack.Enabled=!busy;removeFile.Enabled=!busy;qualityChoice.Enabled=!busy;gifPreview.Enabled=gifEstimate.Enabled=!busy;if(busy)mediaPreview.Stop();LayoutWorkspace();if(!busy)FinishPendingTrayExit();}
